mapper.select:
SELECT cart_id
FROM TB_ITINERARY_CART
WHERE user_id = #{userId}
AND source_itinerary_id = #{itineraryId}

SELECT day_cart_id
FROM TB_ITINERARY_DAY_CART
WHERE cart_id = #{cartId}
AND source_day_id = #{dayId}

SELECT block_cart_id
FROM TB_ITINERARY_BLOCK_CART
WHERE day_cart_id = #{dayCartId}
AND source_block_id = #{blockId}

mapper.delete:
DELETE FROM TB_ITINERARY_CART
WHERE user_id = #{userId}
AND source_itinerary_id = #{itineraryId}

DELETE dc
FROM TB_ITINERARY_DAY_CART dc
JOIN TB_ITINERARY_CART c
ON c.cart_id = dc.cart_id
WHERE c.user_id = #{userId}
AND dc.source_day_id = #{dayId}

mapper.select:
SELECT COUNT(*)
FROM TB_ITINERARY_CART
WHERE user_id = #{value}

mapper.delete:
DELETE dc
FROM TB_ITINERARY_DAY_CART dc
JOIN TB_ITINERARY_CART c
ON c.cart_id = dc.cart_id
LEFT JOIN TB_ITINERARY_BLOCK_CART bc
ON bc.day_cart_id = dc.day_cart_id
WHERE c.user_id = #{userId}
AND c.cart_id = #{cartId}
AND dc.source_day_id = #{dayId}
AND bc.block_cart_id IS NULL
